package controller;
import model.User;import util.DBConnection;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;
public class SupportServlet extends HttpServlet{
 protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException,ServletException{HttpSession h=q.getSession(false);User u=h==null?null:(User)h.getAttribute("user");if(u==null){s.sendRedirect("login.jsp");return;}try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM support_queries WHERE user_id=? ORDER BY created_at DESC")){p.setInt(1,u.getUserId());try(ResultSet r=p.executeQuery()){java.util.List<java.util.Map<String,Object>> rows=new java.util.ArrayList<>();while(r.next()){java.util.Map<String,Object> m=new java.util.LinkedHashMap<>();m.put("id",r.getInt("query_id"));m.put("subject",r.getString("subject"));m.put("message",r.getString("message"));m.put("reply",r.getString("admin_reply"));m.put("status",r.getString("status"));m.put("created",r.getTimestamp("created_at"));rows.add(m);}q.setAttribute("queries",rows);}}catch(SQLException e){throw new ServletException(e);}q.getRequestDispatcher("support.jsp").forward(q,s);}
 protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException,ServletException{HttpSession h=q.getSession(false);User u=h==null?null:(User)h.getAttribute("user");if(u==null){s.sendRedirect("login.jsp");return;}String sub=q.getParameter("subject"),msg=q.getParameter("message");if(sub==null||sub.isBlank()||sub.length()>120||msg==null||msg.isBlank()||msg.length()>3000){q.setAttribute("error","Enter a subject and message (maximum 3000 characters).");doGet(q,s);return;}try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO support_queries(user_id,subject,message) VALUES(?,?,?)")){p.setInt(1,u.getUserId());p.setString(2,sub.trim());p.setString(3,msg.trim());p.executeUpdate();s.sendRedirect("support?sent=1");}catch(SQLException e){throw new ServletException(e);}}
}
